package vn.edu.eaut.lab8.model; import jakarta.validation.constraints.*; public class Sach { private int id; @NotBlank(message="Tên sách không được để trống") private String tenSach; @NotBlank(message="Tác giả không được để trống") private String tacGia; @Min(value=1000,message="Năm xuất bản không hợp lệ") @Max(value=2100,message="Năm xuất bản không hợp lệ") private int namXuatBan; public Sach(){} public Sach(int i,String t,String a,int n){id=i;tenSach=t;tacGia=a;namXuatBan=n;} public int getId(){return id;}public void setId(int v){id=v;}public String getTenSach(){return tenSach;}public void setTenSach(String v){tenSach=v;}public String getTacGia(){return tacGia;}public void setTacGia(String v){tacGia=v;}public int getNamXuatBan(){return namXuatBan;}public void setNamXuatBan(int v){namXuatBan=v;} }
